S = "Hakeem Force Academy"
QS = [
(S, "To which country does Olympic Airlines (now Olympic Air) belong?", ["Turkey", "Greece", "Italy", "Cyprus"], 1,
 "Olympic Airlines was the national flag carrier of Greece, founded in 1957 by Aristotle Onassis. It was replaced by Olympic Air in 2009.",
 "Olympic Airways was nationalised in 1975 and ceased operating as the flag carrier in 2009.", 1),
(S, "To which place did the Holy Prophet (PBUH) migrate in 622 AD?", ["Taif", "Habsha", "Madina", "Jerusalem"], 2,
 "In 622 AD the Prophet (PBUH) migrated from Makkah to Madina (then called Yathrib). This migration is the Hijrat.",
 "The Hijri calendar begins from this migration.", 1),
(S, "To which tribe did Hazrat Ali (RA) belong?", ["Aws", "Banu Thaqif", "Quraysh", "Khazraj"], 2,
 "Hazrat Ali (RA) was born in Makkah into the Banu Hashim clan of the Quraysh tribe. He was the cousin of the Prophet (PBUH).",
 "Aws and Khazraj were the two main tribes of Madina.", 1),
(S, "With which wife of the Prophet (PBUH) was the compiled copy of the Quran kept after Hazrat Abu Bakr (RA) had it collected?", ["Hazrat Ayesha (RA)", "Hazrat Hafsa (RA)", "Hazrat Umm Salama (RA)", "Hazrat Khadija (RA)"], 1,
 "Hazrat Abu Bakr (RA) had the Quran compiled in book form; it passed to Hazrat Umar (RA) and then was kept with his daughter Hazrat Hafsa (RA), the Prophet's wife. Hazrat Usman (RA) later borrowed it to prepare copies.",
 "Hazrat Zaid bin Thabit (RA) led the compilation team under Hazrat Abu Bakr (RA).", 4),
(S, "To whom is the title Zunnurain (possessor of two lights) given?", ["Hazrat Ali (RA)", "Hazrat Umar (RA)", "Hazrat Usman (RA)", "Hazrat Abu Bakr (RA)"], 2,
 "Hazrat Usman (RA) married two daughters of the Prophet (PBUH), Hazrat Ruqayyah and later Hazrat Umm Kulthum (RA), so he is called Zunnurain.",
 "Hazrat Usman (RA) was the third Caliph of Islam.", 1),
(S, "Two daughters of the Holy Prophet (PBUH) were married one after the other to which Sahabi?", ["Hazrat Ali (RA)", "Hazrat Usman (RA)", "Hazrat Umar (RA)", "Hazrat Abu Bakr (RA)"], 1,
 "Hazrat Ruqayyah and, after her death, Hazrat Umm Kulthum (RA) were both married to Hazrat Usman (RA).",
 "Hazrat Fatima (RA), the youngest daughter, was married to Hazrat Ali (RA).", 1),
(S, "Umm Kalsoom (Umm Kulthum) was what of the Holy Prophet (PBUH)?", ["Wife", "Daughter", "Aunt", "Foster mother"], 1,
 "Hazrat Umm Kulthum (RA) was a daughter of the Prophet (PBUH) and Hazrat Khadija (RA).",
 "She married Hazrat Usman (RA) after the death of her sister Hazrat Ruqayyah (RA).", 1),
(S, "Towards which place was the first Hijrat of the Muslims made?", ["Madina", "Taif", "Habsha (Abyssinia)", "Yemen"], 2,
 "In 615 AD a small group of Muslims migrated from Makkah to Habsha (Abyssinia) to escape persecution by the Quraysh. Its Christian king, the Negus, gave them protection.",
 "The migration to Madina came about seven years later, in 622 AD.", 1),
(S, "To whom was the Nishan-e-Haider last awarded?", ["Major Muhammad Akram Shaheed", "Major Raja Aziz Bhatti", "Havaldar Lalak Jan Shaheed", "Major Shabbir Sharif"], 2,
 "Havaldar Lalak Jan Shaheed received the award for gallantry in the 1999 Kargil conflict; no later award is recorded.",
 "Lalak Jan belonged to Yasin valley, Gilgit-Baltistan, and is the 11th recipient.", 1),
(S, "Under the 1960 Indus Waters Treaty, which rivers were allotted to Pakistan?", ["Ravi, Beas and Sutlej", "Indus, Jhelum and Chenab", "Indus, Ravi and Sutlej", "Jhelum, Beas and Chenab"], 1,
 "The treaty gave the three western rivers, Indus, Jhelum and Chenab, to Pakistan and the three eastern rivers, Ravi, Beas and Sutlej, to India.",
 "The treaty was signed in Karachi in September 1960 and mediated by the World Bank.", 1),
(S, "Which system of government was set up by the 1962 Constitution of Pakistan?", ["Parliamentary", "Presidential", "Military rule", "Federal parliamentary with prime minister"], 1,
 "The 1962 Constitution gave all executive power to a strong President, who was elected indirectly by Basic Democrats.",
 "It was introduced by President Ayub Khan.", 2),
(S, "Under which organization is Pakistan's population census conducted?", ["State Bank of Pakistan", "Election Commission of Pakistan", "Pakistan Bureau of Statistics", "NADRA"], 2,
 "Population and housing censuses in Pakistan are carried out by the Pakistan Bureau of Statistics (PBS).",
 "The latest census was the first fully digital one, held in 2023.", 1),
(S, "According to the 2023 census, Urdu is the mother tongue of about what percentage of Pakistanis?", ["About 7.08 percent", "About 9.25 percent", "About 14.3 percent", "About 18.2 percent"], 1,
 "The Pakistan Bureau of Statistics 2023 census puts Urdu at about 9.25 percent of the population. Candidates in 2021-22 recalled about 7 percent, which was the 2017 census figure (7.08 percent).",
 "Punjabi is the most common mother tongue, at about 37 percent.", 1),
(S, "What are both houses of the Parliament of Pakistan (Senate and National Assembly) together called?", ["Majlis-e-Shoora (Parliament)", "Supreme Council", "Federal Cabinet", "Jirga"], 0,
 "Under the 1973 Constitution the Parliament, called Majlis-e-Shoora, consists of the President, the Senate and the National Assembly.",
 "The Senate is the upper house and the National Assembly is the lower house.", 3),
(S, "Which are the three largest oceans of the world, in order of size?", ["Pacific, Atlantic, Indian", "Pacific, Indian, Atlantic", "Atlantic, Pacific, Indian", "Pacific, Atlantic, Arctic"], 0,
 "By area the Pacific is the largest, then the Atlantic, then the Indian Ocean. The Southern and Arctic Oceans are smaller.",
 "The Pacific Ocean covers about one third of the Earth's surface.", 1),
(S, "Which day is celebrated on 12 June?", ["World Environment Day", "World Day Against Child Labour", "World Water Day", "World Population Day"], 1,
 "The International Labour Organization observes the World Day Against Child Labour on 12 June each year.",
 "World Environment Day is on 5 June and World Population Day on 11 July.", 1),
(S, "What did Thomas Edison invent (practically)?", ["Telephone", "Electric bulb", "Radio", "Steam engine"], 1,
 "Thomas Edison developed the first practical long-lasting incandescent electric light bulb in 1879. He also invented the phonograph.",
 "The telephone was patented by Alexander Graham Bell in 1876.", 1),
(S, "What does the word Al-Fatiha mean?", ["The Opening", "The Cow", "The Light", "The Ending"], 0,
 "Al-Fatiha means The Opening, because it opens the Quran and also opens the prayer.",
 "It is also called Umm-ul-Kitab and has seven verses.", 1),
(S, "What does the Arabic word Ansar mean?", ["Emigrants", "Helpers", "Companions", "Warriors"], 1,
 "Ansar means helpers. It refers to the people of Madina who sheltered and helped the Muslims migrating from Makkah.",
 "The migrants from Makkah are called Muhajirin.", 1),
(S, "What does the Arabic word Badr (Badar) mean?", ["Sun", "Full moon", "Well", "Star"], 1,
 "Badr means the full moon in Arabic. The Battle of Badr in 2 AH was fought at a place of that name near Madina.",
 "The Battle of Badr was the first major battle between Muslims and the Quraysh.", 2),
(S, "Uhad (Uhud) is the name of what?", ["A river near Makkah", "A mountain near Madina", "A valley in Taif", "A well in Makkah"], 1,
 "Uhud is a mountain just north of Madina, near which the Battle of Uhud was fought in 3 AH.",
 "The Prophet (PBUH) said that Uhud is a mountain that loves us and we love it.", 1),
(S, "What does the word alter mean?", ["Keep the same", "Change", "Destroy", "Repeat"], 1,
 "To alter something means to change it, usually slightly.",
 "Alter is a verb; its related noun is alteration.", 1),
]
